/**
 * Notification Controller
 * Manages user notifications for session requests, acceptances, ratings, etc.
 * Notifications auto-generated by controllers and marked as read by users
 */

const Notification = require('../models/Notification');

/**
 * Fetch all unread and read notifications for authenticated user
 * @route GET /notification
 * @access Protected (requires JWT token)
 * @returns {array} User's notifications sorted by newest first, with sender info populated
 */
// Get all notifications for current user
const getNotifications = async (req, res) => {
  try {
    const notifications = await Notification.find({ recipient: req.user._id })
      .sort({ createdAt: -1 })
      .populate('sender', 'name avatar');
    res.json(notifications);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

/**
 * Mark single notification as read
 * @route PATCH /notification/:id
 * @access Protected (requires JWT token)
 * @param {string} id - Notification ID
 * @returns {object} Updated notification with isRead = true
 * @throws 404 if notification not found or doesn't belong to user
 */
// Mark notification as read
const markAsRead = async (req, res) => {
  try {
    const notification = await Notification.findById(req.params.id);
    if (notification && notification.recipient.toString() === req.user._id.toString()) {
      notification.isRead = true;
      await notification.save();
      res.json(notification);
    } else {
      res.status(404).json({ message: 'Notification not found' });
    }
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

/**
 * Mark all notifications as read for authenticated user
 * @route PATCH /notification/read-all
 * @access Protected (requires JWT token)
 * @returns {object} {message: 'All notifications marked as read'}
 */
// Mark all as read
const markAllAsRead = async (req, res) => {
  try {
    await Notification.updateMany(
      { recipient: req.user._id, isRead: false },
      { $set: { isRead: true } }
    );
    res.json({ message: 'All notifications marked as read' });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

module.exports = {
  getNotifications,
  markAsRead,
  markAllAsRead
};
